<template>
  <div class="page-api-keys">
    <div class="page-header">
      <h2>{{ t('settings.apiKeys.title') }}</h2>
      <el-button type="primary" @click="onCreate">{{ t('settings.apiKeys.createKey') }}</el-button>
    </div>

    <el-alert
      type="warning"
      :closable="false"
      :title="t('settings.apiKeys.alert')"
      style="margin-bottom: 16px"
    />

    <el-card>
      <DataTable
        :data="keys"
        :loading="loading"
        v-model:current-page="page"
        v-model:page-size="pageSize"
        :total="total"
        server-side
        @page-change="loadKeys"
        @size-change="loadKeys"
      >
        <el-table-column prop="id" label="ID" width="80" />
        <el-table-column prop="name" :label="t('common.name')" min-width="140" />
        <el-table-column prop="prefix" :label="t('settings.apiKeys.prefix')" width="120">
          <template #default="{ row }">
            <code>{{ row.prefix }}…</code>
          </template>
        </el-table-column>
        <el-table-column label="Scopes" min-width="220">
          <template #default="{ row }">
            <el-tag v-for="s in row.scopes" :key="s" size="small" style="margin-right: 4px">
              {{ s }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="rate_limit" :label="t('settings.apiKeys.rateLimitPerMin')" width="100">
          <template #default="{ row }">
            {{ row.rate_limit > 0 ? row.rate_limit : t('common.default') }}
          </template>
        </el-table-column>
        <el-table-column prop="last_used_at" :label="t('settings.apiKeys.lastUsed')" width="180">
          <template #default="{ row }">
            {{ row.last_used_at || t('common.never') }}
          </template>
        </el-table-column>
        <el-table-column prop="enabled" :label="t('common.status')" width="100">
          <template #default="{ row }">
            <el-tag :type="row.enabled ? 'success' : 'info'" size="small">
              {{ row.enabled ? t('common.enabled') : t('settings.apiKeys.revoked') }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column :label="t('common.actions')" width="220" fixed="right">
          <template #default="{ row }">
            <el-button link type="primary" size="small" @click="onToggle(row)">
              {{ row.enabled ? t('settings.apiKeys.revoke') : t('common.enable') }}
            </el-button>
            <el-button link type="primary" size="small" @click="onRotate(row)">
              {{ t('settings.apiKeys.rotate') }}
            </el-button>
          </template>
        </el-table-column>
      </DataTable>
    </el-card>

    <!-- 创建对话框 -->
    <el-dialog
      v-model="dialogVisible"
      :title="t('settings.apiKeys.createDialogTitle')"
      width="560px"
      :close-on-click-modal="false"
      @closed="resetForm"
    >
      <el-form ref="formRef" :model="form" :rules="rules" label-width="120px">
        <el-form-item :label="t('common.name')" prop="name">
          <el-input v-model="form.name" :placeholder="t('settings.apiKeys.namePlaceholder')" />
        </el-form-item>
        <el-form-item :label="t('settings.apiKeys.bindUserId')" prop="user_id">
          <el-input-number v-model="form.user_id" :min="1" controls-position="right" />
        </el-form-item>
        <el-form-item label="Scopes" prop="scopes">
          <el-checkbox-group v-model="form.scopes">
            <el-checkbox v-for="s in ALL_API_SCOPES" :key="s" :label="s" :value="s" />
          </el-checkbox-group>
        </el-form-item>
        <el-form-item :label="t('settings.apiKeys.rateLimitLabel')">
          <el-input-number v-model="form.rate_limit" :min="0" controls-position="right" />
          <span class="form-tip">{{ t('settings.apiKeys.rateLimitTip') }}</span>
        </el-form-item>
        <el-form-item :label="t('settings.apiKeys.expireTime')">
          <el-date-picker
            v-model="form.expires_at"
            type="datetime"
            :placeholder="t('settings.apiKeys.expirePlaceholder')"
            value-format="YYYY-MM-DDTHH:mm:ss"
          />
        </el-form-item>
      </el-form>
      <template #footer>
        <el-button @click="dialogVisible = false">{{ t('common.cancel') }}</el-button>
        <el-button type="primary" :loading="submitting" @click="onSubmit">{{ t('common.create') }}</el-button>
      </template>
    </el-dialog>

    <!-- 一次性明文展示对话框 -->
    <el-dialog
      v-model="keyDialogVisible"
      :title="t('settings.apiKeys.keyDialogTitle')"
      width="560px"
      :close-on-click-modal="false"
    >
      <el-alert
        type="error"
        :closable="false"
        :title="t('settings.apiKeys.keyAlert')"
        style="margin-bottom: 12px"
      />
      <el-input v-model="lastKey" readonly>
        <template #append>
          <el-button @click="copyKey">{{ t('common.copy') }}</el-button>
        </template>
      </el-input>
      <template #footer>
        <el-button type="primary" @click="keyDialogVisible = false">{{ t('common.saved') }}</el-button>
      </template>
    </el-dialog>
  </div>
</template>

<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage, type FormInstance, type FormRules } from 'element-plus'
import {
  ALL_API_SCOPES,
  createApiKey,
  enableApiKey,
  getApiKeys,
  revokeApiKey,
  rotateApiKey,
  type ApiKeyRead,
} from '@/api/apiKeys'
import DataTable from '@/components/common/DataTable.vue'
import { showError } from '@/utils/error'

const { t } = useI18n()
const keys = ref<ApiKeyRead[]>([])
const loading = ref(false)
const page = ref(1)
const pageSize = ref(20)
const total = ref(0)
const dialogVisible = ref(false)
const keyDialogVisible = ref(false)
const lastKey = ref('')
const submitting = ref(false)
const formRef = ref<FormInstance>()

const form = ref<{
  name: string
  user_id: number
  scopes: string[]
  rate_limit: number
  expires_at: string | null
}>({
  name: '',
  user_id: 1,
  scopes: ['read:nodes'],
  rate_limit: 0,
  expires_at: null,
})

const rules: FormRules = {
  name: [{ required: true, message: () => t('settings.apiKeys.nameRequired'), trigger: 'blur' }],
  user_id: [{ required: true, message: () => t('settings.apiKeys.userIdRequired'), trigger: 'blur' }],
  scopes: [
    {
      validator: (_r, v: string[], cb) =>
        v && v.length > 0 ? cb() : cb(new Error(t('settings.apiKeys.scopesRequired'))),
      trigger: 'change',
    },
  ],
}

async function loadKeys() {
  loading.value = true
  try {
    const result = await getApiKeys(page.value, pageSize.value)
    keys.value = result.items
    total.value = result.total
  } catch (error) {
    showError(error, t('settings.apiKeys.loadFailed'))
  } finally {
    loading.value = false
  }
}

function resetForm() {
  form.value = { name: '', user_id: 1, scopes: ['read:nodes'], rate_limit: 0, expires_at: null }
  formRef.value?.resetFields()
}

function onCreate() {
  resetForm()
  dialogVisible.value = true
}

async function onSubmit() {
  const valid = await formRef.value?.validate().catch(() => false)
  if (!valid) return

  submitting.value = true
  try {
    const created = await createApiKey({
      name: form.value.name,
      user_id: form.value.user_id,
      scopes: form.value.scopes,
      rate_limit: form.value.rate_limit,
      expires_at: form.value.expires_at || null,
    })
    dialogVisible.value = false
    lastKey.value = created.key
    keyDialogVisible.value = true
    loadKeys()
  } catch (error) {
    showError(error, t('settings.apiKeys.createFailed'))
  } finally {
    submitting.value = false
  }
}

async function onToggle(row: ApiKeyRead) {
  try {
    if (row.enabled) {
      await revokeApiKey(row.id)
      ElMessage.success(t('settings.apiKeys.revoked'))
    } else {
      await enableApiKey(row.id)
      ElMessage.success(t('settings.apiKeys.enabledMsg'))
    }
    loadKeys()
  } catch (error) {
    showError(error, t('common.updateStatusFailed'))
  }
}

async function onRotate(row: ApiKeyRead) {
  try {
    const rotated = await rotateApiKey(row.id)
    lastKey.value = rotated.key
    keyDialogVisible.value = true
    ElMessage.success(t('settings.apiKeys.rotatedMsg'))
    loadKeys()
  } catch (error) {
    showError(error, t('settings.apiKeys.rotateFailed'))
  }
}

async function copyKey() {
  try {
    await navigator.clipboard.writeText(lastKey.value)
    ElMessage.success(t('common.copySuccess'))
  } catch {
    ElMessage.warning(t('settings.apiKeys.copyFailedManual'))
  }
}

onMounted(() => {
  loadKeys()
})
</script>

<style scoped>
.page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}

.page-header h2 {
  margin: 0;
}

.form-tip {
  margin-left: 12px;
  color: var(--el-text-color-secondary);
  font-size: 12px;
}
</style>
