import apiClient from './client'
import type { Page } from './page'

/** 开放 API 支持的 scope，与后端 VALID_API_SCOPES 保持一致。 */
export const ALL_API_SCOPES = [
  'read:metrics',
  'read:alerts',
  'read:incidents',
  'read:nodes',
  'read:alert_rules',
  'write:alert_rules',
  'read:notification_channels',
  'write:notification_channels',
  'read:webhooks',
] as const

export type ApiScope = (typeof ALL_API_SCOPES)[number]

export interface ApiKeyRead {
  id: number
  name: string
  prefix: string
  user_id: number
  scopes: string[]
  rate_limit: number
  last_used_at: string | null
  expires_at: string | null
  enabled: boolean
  created_at: string
}

export interface ApiKeyCreate {
  name: string
  user_id: number
  scopes: string[]
  rate_limit?: number
  expires_at?: string | null
}

/** 创建/轮转响应：额外包含仅此一次可见的明文 key。 */
export interface ApiKeyCreateResponse extends ApiKeyRead {
  key: string
}

const BASE = '/v1/admin/api-keys'

export async function getApiKeys(page = 1, pageSize = 20): Promise<Page<ApiKeyRead>> {
  const response = await apiClient.get<Page<ApiKeyRead>>(BASE, {
    params: { page, page_size: pageSize },
  })
  return response.data
}

export async function createApiKey(data: ApiKeyCreate): Promise<ApiKeyCreateResponse> {
  const response = await apiClient.post<ApiKeyCreateResponse>(BASE, data)
  return response.data
}

export async function revokeApiKey(id: number): Promise<void> {
  await apiClient.delete(`${BASE}/${id}`)
}

export async function enableApiKey(id: number): Promise<ApiKeyRead> {
  const response = await apiClient.post<ApiKeyRead>(`${BASE}/${id}/enable`)
  return response.data
}

export async function rotateApiKey(id: number): Promise<ApiKeyCreateResponse> {
  const response = await apiClient.post<ApiKeyCreateResponse>(`${BASE}/${id}/rotate`)
  return response.data
}
